
    @font-face {
      font-family: 'SF Pro Display';
      src: url('fonts/font-1.woff') format('woff');
      font-weight: 100;
      font-style: normal;
      font-display: swap;
    }
    @font-face {
      font-family: 'SF Pro Display';
      src: url('fonts/font-2.woff') format('woff');
      font-weight: 400;
      font-style: normal;
      font-display: swap;
    }
    @font-face {
      font-family: 'SF Pro Display';
      src: url('fonts/font-3.woff') format('woff');
      font-weight: 500;
      font-style: normal;
      font-display: swap;
    }
    @font-face {
      font-family: 'SF Pro Display';
      src: url('fonts/font-4.woff') format('woff');
      font-weight: 600;
