      font-display: swap;
    }
    @font-face {
      font-family: 'SF Pro Rounded';
      src: url('fonts/font-6.woff') format('woff');
      font-weight: 400;
      font-style: normal;
      font-display: swap;
    }
    @font-face {
      font-family: 'SF Pro Rounded';
      src: url('fonts/font-7.woff') format('woff');
      font-weight: 500;
      font-style: normal;
      font-display: swap;
    }
    @font-face {
      font-family: 'SF Pro Rounded';
      src: url('fonts/font-8.woff') format('woff');
      font-weight: 700;
      font-style: normal;
      font-display: swap;
    }
  

    @font-face {
      font-family: 'IOSTGICO';
      src: url('data:font/ttf;base64,') format('truetype');
      font-weight: normal;
      font-style: normal;
      font-display: block;
    }
    .tg-ico {
      font-family: 'IOSTGICO' !important;
      font-style: normal;
      font-weight: normal !important;
      line-height: 1;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      -webkit-font-smoothing: antialiased;
    }

    :root {
      --bg-outer: #080d14;
      --bg-app: #0E1621;
      --bg-card: #17212B;
      --bg-elevated: #232E3C;
      --bg-input: #0E1621;
      --text-primary: #ffffff;
      --text-secondary: #7F91A4;
      --text-muted: #7F91A4;
      --ring-track: rgba(255, 255, 255, 0.12);
      --switch-off: #39393D;
      --border-hairline: rgba(255, 255, 255, 0.06);
      --card-shadow: 0 4px 18px rgba(0, 0, 0, 0.28);
      --pill-shadow: 0 2px 10px rgba(0, 0, 0, 0.24);
      --glass-bg: rgba(23, 33, 43, 0.92);
      --glass-border: rgba(255, 255, 255, 0.08);
      --glass-active: rgba(255, 255, 255, 0.10);
      --tab-inactive: #ffffff;
      --play-btn-bg: #ffffff;
      --play-btn-fg: #0E1621;
    }

    body.theme-light {
      --bg-outer: #e5e7eb;
      --bg-app: #F3F3F7;
      --bg-card: #FFFFFF;
      --bg-elevated: #E9E9EE;
      --bg-input: #F3F3F7;
      --text-primary: #000000;
      --text-secondary: #8E8E93;
      --text-muted: #8E8E93;
      --ring-track: rgba(0, 0, 0, 0.08);
      --switch-off: #D1D1D6;
      --border-hairline: rgba(0, 0, 0, 0.05);
      --card-shadow: 0 2px 12px rgba(0, 0, 0, 0.045);
      --pill-shadow: 0 2px 10px rgba(0, 0, 0, 0.06);
      --glass-bg: rgba(255, 255, 255, 0.90);
      --glass-border: rgba(0, 0, 0, 0.06);
      --glass-active: rgba(120, 120, 128, 0.14);
      --tab-inactive: #000000;
      --play-btn-bg: #000000;
      --play-btn-fg: #ffffff;
    }

    * {
      font-family: 'SF Pro Display', -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'Helvetica Neue', sans-serif;
      -webkit-tap-highlight-color: transparent;
      -webkit-font-smoothing: antialiased;
    }

    .font-rounded {
      font-family: 'SF Pro Rounded', ui-rounded, 'SF Pro Display', -apple-system, BlinkMacSystemFont, sans-serif;
      font-weight: 800;
    }

    body {
      background-color: var(--bg-outer);
      color: var(--text-primary);
      overflow-x: hidden;
      transition: background-color 0.2s ease, color 0.2s ease;
    }
    .app-surface {
      background-color: var(--bg-app);
      color: var(--text-primary);
      transition: background-color 0.2s ease, color 0.2s ease;
    }
    .no-scrollbar::-webkit-scrollbar { display: none; }
    .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

    @keyframes heartPop {
      0% { transform: scale(1); }
      35% { transform: scale(1.42); }
      65% { transform: scale(0.88); }
      100% { transform: scale(1); }
    }
    @keyframes heartUnpop {
      0% { transform: scale(1); }
      40% { transform: scale(0.72) rotate(-10deg); }
      100% { transform: scale(1) rotate(0deg); }
    }
    .anim-like-pop { animation: heartPop 0.38s cubic-bezier(0.34, 1.56, 0.64, 1); }
    @keyframes tabIconBounce {
      0% { transform: scale(1); }
      40% { transform: scale(1.22) translateY(-2px); }
      70% { transform: scale(0.94); }
      100% { transform: scale(1); }
    }
    @keyframes maxGradFlow {
      0% { background-position: 0% 50%; }
      50% { background-position: 100% 50%; }
      100% { background-position: 0% 50%; }
    }
    .max-hero-gradient {
      background: linear-gradient(125deg, #2AABEE, #5B6CF9, #A855F7, #EC4899, #2AABEE);
      background-size: 260% 260%;
      animation: maxGradFlow 9s ease infinite;
    }
    @keyframes starTwinkle {
      0%, 100% { opacity: 0.25; transform: scale(0.7) rotate(0deg); }
      50% { opacity: 0.95; transform: scale(1.25) rotate(18deg); }
    }
    .max-star {
      position: absolute;
      color: #ffffff;
      font-weight: 700;
      user-select: none;
      pointer-events: none;
      animation: starTwinkle 2.6s ease-in-out infinite;
    }
    /* Unified Native Telegram iOS Bottom-Sheet Modal System */
    @keyframes tgBackdropIn {
      0% { opacity: 0; }
      100% { opacity: 1; }
    }
    @keyframes tgBackdropOut {
      0% { opacity: 1; }
      100% { opacity: 0; }
    }
    @keyframes tgSheetIn {
      0% { opacity: 1; transform: translate3d(0, 100%, 0); }
      100% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
    }
    @keyframes tgSheetOut {
      0% { opacity: 1; transform: translate3d(0, var(--sheet-drag-y, 0px), 0) scale(1); }
      100% { opacity: 1; transform: translate3d(0, 100%, 0); }
    }
    .tg-sheet-modal {
      will-change: opacity;
    }
    .tg-sheet-modal .col-sheet-panel {
      --sheet-drag-y: 0px;
      will-change: transform, opacity;
      transform: translate3d(0, 0, 0);
    }
    .tg-sheet-modal.is-open,
    #profile-bg-modal.is-open,
    #library-modal.is-open,
    #collection-modal.is-open,
    #artist-modal.is-open,
    #settings-modal.is-open,
    #mytelefy-upsell-modal.is-open,
    #create-playlist-modal.is-open,
    #album-modal.is-open {
      animation: tgBackdropIn 0.28s cubic-bezier(0.22, 1, 0.36, 1) forwards;
    }
    .tg-sheet-modal.is-open .col-sheet-panel,
    #profile-bg-modal.is-open .col-sheet-panel,
    #library-modal.is-open .col-sheet-panel,
    #collection-modal.is-open .col-sheet-panel,
    #artist-modal.is-open .col-sheet-panel,
    #settings-modal.is-open .col-sheet-panel,
    #mytelefy-upsell-modal.is-open .col-sheet-panel,
    #create-playlist-modal.is-open .col-sheet-panel,
    #album-modal.is-open .col-sheet-panel {
      animation: tgSheetIn 0.42s cubic-bezier(0.32, 0.72, 0, 1) forwards;
    }
    .tg-sheet-modal.is-closing,
    #profile-bg-modal.is-closing,
    #library-modal.is-closing,
    #collection-modal.is-closing,
    #artist-modal.is-closing,
    #settings-modal.is-closing,
    #mytelefy-upsell-modal.is-closing,
    #create-playlist-modal.is-closing,
    #album-modal.is-closing {
      animation: tgBackdropOut 0.30s cubic-bezier(0.32, 0.72, 0, 1) forwards;
      pointer-events: none;
    }
    .tg-sheet-modal.is-closing .col-sheet-panel,
    #profile-bg-modal.is-closing .col-sheet-panel,
    #library-modal.is-closing .col-sheet-panel,
    #collection-modal.is-closing .col-sheet-panel,
    #artist-modal.is-closing .col-sheet-panel,
    #settings-modal.is-closing .col-sheet-panel,
    #mytelefy-upsell-modal.is-closing .col-sheet-panel,
    #create-playlist-modal.is-closing .col-sheet-panel,
    #album-modal.is-closing .col-sheet-panel {
      animation: tgSheetOut 0.28s cubic-bezier(0.32, 0.72, 0, 1) forwards;
    }

    @keyframes coverShimmer {
      0% { background-position: -150% 0; }
      100% { background-position: 150% 0; }
    }
    .cover-loading::after {
      content: '';
      position: absolute;
      inset: 0;
      z-index: 2;
      background: linear-gradient(110deg, transparent 25%, rgba(255,255,255,0.16) 50%, transparent 75%);
      background-size: 200% 100%;
      animation: coverShimmer 1.3s ease-in-out infinite;
      pointer-events: none;
    }
    .cover-art-img {
      position: absolute;
      inset: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
      object-position: center;
      display: block;
      pointer-events: none;
      user-select: none;
      -webkit-user-drag: none;
      z-index: 0;
    }

    /* Unified Organic Spring Motion Across Entire App */
    button, .track-play-trigger, .upl-card, .col-card {
      transition: transform 0.22s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.18s ease, background-color 0.2s ease, color 0.2s ease, box-shadow 0.2s ease;
      -webkit-tap-highlight-color: transparent;
    }
    button:not(.tg-row):not(.tg-profile-music-bar):not([data-pick-track]):not(#btn-hero-play):active {
      transform: scale(0.95);
    }
    .tg-row {
      transition: background-color 0.16s ease, transform 0.18s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.2s ease;
    }
    .tg-row:active, [data-pick-track]:active {
      transform: scale(0.992);
      background-color: var(--glass-active);
    }
    .tg-profile-music-bar:active {
      background-color: rgba(0, 0, 0, 0.34);
    }
    @keyframes viewEnter {
      0% { opacity: 0; transform: translate3d(0, 8px, 0) scale(0.992); }
      100% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
    }
    .view-entering {
      animation: viewEnter 0.28s cubic-bezier(0.22, 1, 0.36, 1) forwards;
    }
    @keyframes sheetSlideUp {
      0% { opacity: 0; transform: translate3d(0, 18px, 0) scale(0.985); }
      100% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
    }
    .sheet-entering {
      animation: sheetSlideUp 0.3s cubic-bezier(0.22, 1, 0.36, 1) forwards;
    }
    @keyframes heroTapPulse {
      0% { transform: scale(1); }
      35% { transform: scale(0.94); }
      75% { transform: scale(1.025); }
      100% { transform: scale(1); }
    }
    .hero-tap-pulse {
      animation: heroTapPulse 0.32s cubic-bezier(0.34, 1.56, 0.64, 1);
    }
    @keyframes checkPop {
      0% { transform: scale(0.75); }
      55% { transform: scale(1.18); }
      100% { transform: scale(1); }
    }
    .anim-check-pop {
      animation: checkPop 0.26s cubic-bezier(0.34, 1.56, 0.64, 1);
    }

    .tab-bouncing .tg-ico, .tab-bouncing svg {
      animation: tabIconBounce 0.38s cubic-bezier(0.34, 1.56, 0.64, 1);
    }
    #tab-active-lens {
      position: absolute;
      top: 6px;
      bottom: 6px;
      left: 6px;
      width: calc((100% - 12px) / 4);
      border-radius: 9999px;
      background-color: var(--glass-active);
      transition: transform 0.36s cubic-bezier(0.32, 0.72, 0, 1);
      pointer-events: none;
      z-index: 0;
    }
    #full-player-modal {
      will-change: transform, opacity;
      transition: transform 0.36s cubic-bezier(0.32, 0.72, 0, 1), opacity 0.26s cubic-bezier(0.22, 1, 0.36, 1);
    }
    #full-player-modal.sheet-closed {
      transform: translate3d(0, 100%, 0) scale(0.985);
      opacity: 0;
      pointer-events: none;
    }
    #full-player-modal.sheet-open {
      transform: translate3d(0, 0, 0) scale(1);
      opacity: 1;
    }
    #full-lyrics-box {
      transition: opacity 0.26s cubic-bezier(0.22, 1, 0.36, 1);
    }
    #full-lyrics-box.lyrics-hidden {
      opacity: 0;
      pointer-events: none;
    }
    #full-lyrics-box.lyrics-visible {
      opacity: 1;
      pointer-events: auto;
    }
    #full-cover { isolation:isolate; }
    .full-cover-layer { position:absolute; inset:0; z-index:0; display:flex; align-items:center; justify-content:center; pointer-events:none; }

    .anim-like-unpop { animation: heartUnpop 0.32s ease-out; }

    /* Squircle System — Super-Rounded Telegram Geometry */
    .squircle { corner-shape: squircle; }
    .squircle-card {
      border-radius: 26px;
      corner-shape: squircle;
      background-color: var(--bg-card);
      box-shadow: var(--card-shadow);
    }
    .squircle-cover-lg { border-radius: 36px; corner-shape: squircle; }
    .squircle-cover-md { border-radius: 24px; corner-shape: squircle; }
    .squircle-cover-sm { border-radius: 14px; corner-shape: squircle; }
    .squircle-btn { border-radius: 22px; corner-shape: squircle; }

    /* Clean Solid Liquid Glass (Zero Glow / No Gradients) */
    .liquid-glass {
      background-color: var(--glass-bg);
      backdrop-filter: blur(18px) saturate(120%);
      -webkit-backdrop-filter: blur(18px) saturate(120%);
      border: 1px solid var(--glass-border);
      box-shadow: 0 4px 14px rgba(0, 0, 0, 0.06);
    }
    .glass-circle-btn {
      background-color: var(--bg-card);
      box-shadow: var(--pill-shadow);
    }
    .nav-tab {
      color: var(--tab-inactive);
      position: relative;
      z-index: 1;
      transition: color 0.22s ease, transform 0.15s ease;
    }
    .nav-tab:active {
      transform: scale(0.92);
    }
    .nav-tab.active-glass {
      color: #2AABEE;
    }

    /* Super-Rounded Telegram Grouped Card */
    .tg-card {
      background-color: var(--bg-card);
      border-radius: 26px;
      corner-shape: squircle;
      box-shadow: var(--card-shadow);
      overflow: hidden;
    }
    .tg-row {
      position: relative;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 12px 16px;
      transition: background-color 0.15s ease;
    }
    .tg-row:active, .tg-row:hover {
      background-color: rgba(128, 128, 128, 0.06);
    }
    .tg-row + .tg-row::before {
      content: '';
      position: absolute;
      top: 0;
      left: 62px;
      right: 0;
      height: 0.5px;
      background-color: var(--border-hairline);
    }
    .tg-icon-box {
      width: 30px;
      height: 30px;
      border-radius: 10px;
      corner-shape: squircle;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      color: #ffffff;
      box-shadow: none;
    }
    @keyframes tgIconLevitate {
      0%, 100% {
        transform: translate3d(0, 0, 0) rotate(var(--r, 0deg));
      }
      50% {
        transform: translate3d(0, -6px, 0) rotate(calc(var(--r, 0deg) + var(--dr, 4deg)));
      }
    }
    .tg-profile-float-ico {
      animation: tgIconLevitate var(--dur, 4.4s) ease-in-out infinite;
      animation-delay: var(--delay, 0s);
      will-change: transform;
    }

    /* Native Telegram Profile Header Pattern */
    .tg-profile-header {
      background: linear-gradient(160deg, #4B6B8A 0%, #3A5775 55%, #2D4661 100%);
      position: relative;
      overflow: hidden;
    }
    .tg-profile-pattern {
      position: absolute;
      inset: 0;
      opacity: 0.12;
      background-image: radial-gradient(circle at 20% 25%, #ffffff 1.2px, transparent 1.2px),
                        radial-gradient(circle at 75% 20%, #ffffff 1.5px, transparent 1.5px),
                        radial-gradient(circle at 45% 70%, #ffffff 1.2px, transparent 1.2px),
                        radial-gradient(circle at 85% 75%, #ffffff 1.4px, transparent 1.4px);
      background-size: 90px 90px;
      pointer-events: none;
    }
    .tg-profile-music-bar {
      background: rgba(0, 0, 0, 0.22);
      backdrop-filter: blur(10px);
      -webkit-backdrop-filter: blur(10px);
      border-top: 0.5px solid rgba(255, 255, 255, 0.14);
    }
    .text-muted { color: var(--text-secondary); }
    .bg-elevated { background-color: var(--bg-elevated); }
    .play-circle-btn {
      background-color: var(--play-btn-bg);
      color: var(--play-btn-fg);
    }

    input[type="range"] {
      -webkit-appearance: none;
      appearance: none;
      background: transparent;
      cursor: pointer;
    }
    input[type="range"]::-webkit-slider-runnable-track {
      height: 4px;
      border-radius: 999px;
    }
    input[type="range"]::-webkit-slider-thumb {
      -webkit-appearance: none;
      appearance: none;
      width: 13px;
      height: 13px;
      border-radius: 999px;
      background: #2AABEE;
      margin-top: -4.5px;
      box-shadow: none;
    }

    #full-seek-slider { touch-action:pan-y; }
    #full-seek-slider::-webkit-slider-thumb {
      transform:scale(1);
      transform-origin:center;
      transition:transform .24s cubic-bezier(.22,1,.36,1);
    }
    #full-seek-slider.is-seeking::-webkit-slider-thumb {
      transform:scale(1.8);
      transition:transform .3s cubic-bezier(.34,1.56,.64,1);
    }
    #full-seek-slider::-moz-range-track { height:4px; background:transparent; }
    #full-seek-slider::-moz-range-thumb {
      width:13px; height:13px; border:0; border-radius:50%; background:#2AABEE;
      transform:scale(1); transform-origin:center;
      transition:transform .24s cubic-bezier(.22,1,.36,1);
    }
    #full-seek-slider.is-seeking::-moz-range-thumb {
      transform:scale(1.8);
      transition:transform .3s cubic-bezier(.34,1.56,.64,1);
    }
    @media (prefers-reduced-motion:reduce) {
      #full-seek-slider::-webkit-slider-thumb { transition:none; }
      #full-seek-slider.is-seeking::-webkit-slider-thumb { transition:none; }
      #full-seek-slider::-moz-range-thumb { transition:none; }
      #full-seek-slider.is-seeking::-moz-range-thumb { transition:none; }
    }

    /* Telegram-style Toggle Switches — Solid #2AABEE, Zero Glow */
    .tg-switch {
      position: relative;
      display: inline-flex;
      align-items: center;
      width: 52px;
      height: 31px;
      flex-shrink: 0;
      cursor: pointer;
    }
    .tg-switch input {
      position: absolute;
      opacity: 0;
      width: 0;
      height: 0;
    }
    .tg-switch-track {
      width: 100%;
      height: 100%;
      border-radius: 9999px;
      background-color: var(--switch-off);
      box-shadow: none !important;
      transition: background-color 0.22s cubic-bezier(0.22, 1, 0.36, 1);
      position: relative;
    }
    .tg-switch input:checked + .tg-switch-track {
      background-color: #2AABEE;
      box-shadow: none !important;
    }
    .tg-switch-thumb {
      position: absolute;
      top: 2px;
      left: 2px;
      width: 27px;
      height: 27px;
      border-radius: 9999px;
      background-color: #ffffff;
      box-shadow: none !important;
      transition: transform 0.26s cubic-bezier(0.34, 1.45, 0.64, 1), width 0.15s ease;
    }
    .tg-switch input:checked + .tg-switch-track .tg-switch-thumb {
      transform: translateX(21px);
    }
    .tg-switch:active .tg-switch-thumb {
      width: 31px;
    }
    .tg-switch:active input:checked + .tg-switch-track .tg-switch-thumb {
      transform: translateX(17px);
    }

    /* Telegram-style RU / EN Pill Switch — Solid #2AABEE, Zero Glow */
    .tg-lang-switch {
      position: relative;
      display: inline-grid;
      grid-template-columns: 1fr 1fr;
      align-items: center;
      width: 80px;
      height: 31px;
      padding: 2px;
      border-radius: 9999px;
      background-color: var(--switch-off);
      box-shadow: none !important;
      cursor: pointer;
      user-select: none;
      flex-shrink: 0;
      transition: background-color 0.2s ease;
    }
    .tg-lang-thumb {
      position: absolute;
      top: 2px;
      left: 2px;
      width: 38px;
      height: 27px;
      border-radius: 9999px;
      background-color: #2AABEE;
      box-shadow: none !important;
      transition: transform 0.26s cubic-bezier(0.34, 1.45, 0.64, 1);
      z-index: 0;
    }
    .tg-lang-switch[data-lang="en"] .tg-lang-thumb {
      transform: translateX(38px);
    }
    .tg-lang-opt {
      position: relative;
      z-index: 1;
      text-align: center;
      font-size: 11px;
      font-weight: 800;
      font-family: 'SF Pro Rounded', ui-rounded, 'SF Pro Display', -apple-system, sans-serif;
      letter-spacing: 0.02em;
      color: var(--text-muted);
      transition: color 0.2s ease;
    }
    .tg-lang-switch[data-lang="ru"] .tg-lang-opt[data-opt="ru"],
    .tg-lang-switch[data-lang="en"] .tg-lang-opt[data-opt="en"] {
      color: #ffffff;
    }
    .tg-section-label {
      font-size: 12px;
      font-weight: 800;
      font-family: 'SF Pro Rounded', ui-rounded, 'SF Pro Display', -apple-system, sans-serif;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      color: var(--text-muted);
      padding: 0 14px;
    }
    /* Segmented Tabs in Telefy Max Beta */
    .max-seg-bar {
      position: relative;
      display: grid;
      grid-template-columns: 1fr 1fr;
